import queue  # noqa: F401  (used by the implementation)

import pytest


def accepted(cap: int, xs: list[int]) -> int:
    """Count how many of xs a bounded queue of capacity cap accepts.

    Create a queue holding at most cap integers and try to put each element
    of xs in order without blocking. Stop at the first rejected put (queue
    full) and return the number of puts accepted before that. A cap of 0 or
    less accepts nothing, so the result is 0 (it is not treated as an
    unbounded queue).
    """
    if cap <= 0:
        return 0
    q: queue.Queue[int] = queue.Queue(maxsize=cap)
    count = 0
    for x in xs:
        try:
            q.put_nowait(x)
        except queue.Full:
            break
        count += 1
    return count


def test_more_items_than_capacity() -> None:
    assert accepted(3, [1, 2, 3, 4, 5]) == 3


def test_fewer_items_than_capacity() -> None:
    assert accepted(10, [1, 2, 3]) == 3


def test_exact_fit() -> None:
    assert accepted(3, [7, 8, 9]) == 3


def test_empty_input() -> None:
    assert accepted(5, []) == 0


def test_zero_capacity() -> None:
    assert accepted(0, [1, 2, 3]) == 0


def test_negative_capacity() -> None:
    assert accepted(-2, [1, 2]) == 0


def test_capacity_one() -> None:
    assert accepted(1, [4, 4, 4]) == 1


def test_duplicates_and_negatives_count() -> None:
    assert accepted(4, [-1, -1, 0, 0, 5]) == 4


@pytest.mark.parametrize(
    ("cap", "xs", "expected"),
    [
        (2, [1], 1),
        (2, [1, 2], 2),
        (2, [1, 2, 3], 2),
        (0, [], 0),
        (100, list(range(1000)), 100),
    ],
)
def test_parametrized(cap: int, xs: list[int], expected: int) -> None:
    assert accepted(cap, xs) == expected


def test_input_not_mutated() -> None:
    xs = [1, 2, 3, 4]
    accepted(2, xs)
    assert xs == [1, 2, 3, 4]

